def transform(grid):
    h=len(grid); w=len(grid[0])
    bad={row[0] for row in grid}
    col=None
    for i in range(h):
        for j in range(w):
            if grid[i][j] not in bad:
                col=grid[i][j]; break
        if col is not None: break
    rs=[i for i in range(h) for j in range(w) if grid[i][j]==col]
    cs=[j for i in range(h) for j in range(w) if grid[i][j]==col]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    return [[grid[i][j] if grid[i][j]==col else 0 for j in range(c0,c1+1)] for i in range(r0,r1+1)]
